function ChapterReader({ chapterId, onBack }) {
  const chapter = useMemo(() => CHAPTERS.find((item) => item.id === chapterId), [chapterId]);
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => setCurrentIndex(0), [chapterId]);

  if (!chapter) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center bg-zinc-50 dark:bg-zinc-950">
        <i className="fa-solid fa-book-open mb-4 text-3xl text-zinc-400"></i>
        <h2 className="text-xl font-bold text-zinc-900 dark:text-white">Chapter not found</h2>
        <button onClick={onBack} className="mt-6 rounded-lg bg-blue-600 px-6 py-2 font-semibold text-white">Go Back</button>
      </div>
    );
  }

  const hasPages = chapter.pages?.length > 0;

  return (
    <div className="min-h-screen bg-zinc-50 dark:bg-zinc-950">
      <div className="fixed top-0 z-50 w-full border-b border-zinc-200 bg-white/95 backdrop-blur-md dark:border-zinc-800 dark:bg-zinc-950/95">
        <div className="mx-auto flex max-w-5xl items-center gap-4 px-6 py-4">
          <button onClick={onBack} className="flex h-10 w-10 items-center justify-center rounded-full text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800 dark:hover:text-white">
            <i className="fa-solid fa-arrow-left"></i>
          </button>
          <div className="min-w-0 flex-1">
            <h1 className="truncate text-lg font-bold text-zinc-900 dark:text-white">Chapter {chapter.chapterNumber}</h1>
            <p className="truncate text-sm text-zinc-500 dark:text-zinc-400">{chapter.title}</p>
          </div>
        </div>
      </div>

      <div className="px-6 pb-24 pt-28">
        {hasPages ? (
          <div className="mx-auto max-w-3xl">
            <img src={chapter.pages[currentIndex]} alt={`Page ${currentIndex + 1}`} className="mx-auto max-h-[80vh] w-full rounded-lg object-contain shadow-sm" />
            <div className="mt-6 flex items-center justify-between gap-4">
              <button onClick={() => setCurrentIndex((i) => Math.max(0, i - 1))} disabled={currentIndex === 0} className="flex-1 rounded-xl bg-zinc-200 py-3 font-medium disabled:opacity-30 dark:bg-zinc-800 dark:text-white">← Prev</button>
              <span className="text-sm text-zinc-500">Page {currentIndex + 1} of {chapter.pages.length}</span>
              <button onClick={() => setCurrentIndex((i) => Math.min(chapter.pages.length - 1, i + 1))} disabled={currentIndex === chapter.pages.length - 1} className="flex-1 rounded-xl bg-zinc-900 py-3 font-medium text-white disabled:opacity-30 dark:bg-white dark:text-black">Next →</button>
            </div>
          </div>
        ) : (
          <div className="mx-auto flex min-h-[60vh] max-w-3xl flex-col items-center justify-center rounded-2xl border-2 border-dashed border-zinc-200 bg-white px-6 text-center dark:border-zinc-800 dark:bg-zinc-900">
            <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-zinc-100 text-zinc-300 dark:bg-zinc-800 dark:text-zinc-600">
              <i className="fa-solid fa-file-circle-xmark text-2xl"></i>
            </div>
            <h3 className="font-semibold text-zinc-900 dark:text-white">Chapter content is not uploaded yet</h3>
            <p className="mt-2 max-w-md text-zinc-500">The chapter structure is ready. Manga pages can be connected through Supabase Storage in the next phase.</p>
            <button onClick={onBack} className="mt-6 rounded-lg bg-blue-600 px-6 py-2 font-semibold text-white">Back to Chapters</button>
          </div>
        )}
      </div>
    </div>
  );
}

