// --- src/components/modals/ReviewModal.jsx ---
const storageKey = (storyId) => `atma-rekha-reviews:${storyId}`;

function ReviewModal({ isOpen, onClose, storyId, storyTitle }) {
  const [name, setName] = useState('');
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState('');
  const [reviews, setReviews] = useState([]);

  useEffect(() => {
    if (!isOpen || !storyId) return;
    try {
      setReviews(JSON.parse(localStorage.getItem(storageKey(storyId)) || '[]'));
    } catch {
      setReviews([]);
    }
  }, [isOpen, storyId]);

  const handleSubmit = (event) => {
    event.preventDefault();
    const review = {
      id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now()),
      user: name.trim() || 'Anonymous',
      rating,
      comment: comment.trim(),
      createdAt: new Date().toISOString(),
    };
    if (!review.comment) return;

    const next = [review, ...reviews];
    setReviews(next);
    localStorage.setItem(storageKey(storyId), JSON.stringify(next));
    setName('');
    setRating(5);
    setComment('');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[2000] flex items-center justify-center bg-black/60 px-4 backdrop-blur-sm">
      <div className="flex h-[90vh] w-full max-w-4xl flex-col overflow-hidden rounded-2xl bg-white shadow-xl dark:bg-zinc-900 md:flex-row">
        <div className="w-full overflow-y-auto p-6 md:w-1/2 md:border-r md:border-zinc-200 dark:md:border-zinc-800">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="text-xl font-bold dark:text-white">Review: {storyTitle}</h2>
            <button onClick={onClose} className="text-zinc-500 hover:text-zinc-900 dark:hover:text-white">
              <i className="fa-solid fa-xmark text-xl"></i>
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full rounded-lg border border-zinc-200 bg-transparent px-4 py-2 dark:border-zinc-700 dark:text-white"
              placeholder="Your name"
            />
            <div>
              <label className="mb-1.5 block text-sm font-medium text-zinc-700 dark:text-zinc-300">Rating</label>
              <div className="flex gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button key={star} type="button" onClick={() => setRating(star)} className={`text-2xl ${rating >= star ? 'text-yellow-400' : 'text-zinc-300 dark:text-zinc-700'}`}>
                    <i className="fa-solid fa-star"></i>
                  </button>
                ))}
              </div>
            </div>
            <textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              className="w-full rounded-lg border border-zinc-200 bg-transparent px-4 py-2 dark:border-zinc-700 dark:text-white"
              rows="4"
              placeholder="What did you think?"
              required
            />
            <button type="submit" className="w-full rounded-lg bg-blue-600 py-2.5 font-medium text-white hover:bg-blue-700">
              Save Review
            </button>
          </form>
        </div>

        <div className="flex w-full flex-col bg-zinc-50 dark:bg-zinc-950 md:w-1/2">
          <div className="flex items-center justify-between border-b border-zinc-200 px-6 py-4 dark:border-zinc-800">
            <h3 className="font-semibold text-zinc-900 dark:text-white">Community Reviews ({reviews.length})</h3>
            <button onClick={onClose} className="text-zinc-500 hover:text-zinc-900 dark:hover:text-white">
              <i className="fa-solid fa-xmark text-xl"></i>
            </button>
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto p-6">
            {reviews.length === 0 ? (
              <p className="text-center text-sm text-zinc-500">No reviews yet. Be the first to review!</p>
            ) : reviews.map((review) => (
              <div key={review.id} className="rounded-xl border border-zinc-200 bg-white p-4 shadow-sm dark:border-zinc-800 dark:bg-zinc-900">
                <div className="mb-2 flex items-center justify-between">
                  <span className="font-medium text-zinc-900 dark:text-white">{review.user}</span>
                  <span className="text-xs text-zinc-400">{new Date(review.createdAt).toLocaleDateString()}</span>
                </div>
                <div className="mb-2 flex text-xs text-yellow-400">
                  {[1, 2, 3, 4, 5].map((star) => <i key={star} className={star <= review.rating ? 'fa-solid fa-star' : 'fa-regular fa-star text-zinc-300 dark:text-zinc-700'} />)}
                </div>
                <p className="text-sm text-zinc-600 dark:text-zinc-300">{review.comment}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

// --- src/components/modals/ComingSoonModal.jsx ---
function ComingSoonModal({ isOpen, onClose }) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[3000] flex items-center justify-center bg-black/70">
      <div className="w-[420px] max-w-[90%] rounded-2xl border border-zinc-200 bg-white p-8 text-center dark:border-zinc-800 dark:bg-zinc-900">
        <h2 className="mb-3 text-2xl font-semibold text-zinc-900 dark:text-white">Coming Soon</h2>
        <p className="text-sm text-zinc-500 dark:text-zinc-400">
          We're working hard to bring the publishing feature to you soon. Stay tuned!
        </p>
        <button onClick={onClose} className="mt-6 rounded-full bg-white px-6 py-2 text-sm font-semibold text-black shadow-md">
          Close
        </button>
      </div>
    </div>
  );
}

// --- src/components/modals/CommentsSheet.jsx ---
function CommentsSheet({ isOpen, activeChapter, comments, inputValue, onInputChange, nameValue, onNameChange, onSubmit, onClose }) {
  if (!isOpen) return null;

  return (
    <>
      <div className="fixed inset-0 z-[1900] bg-black/80" onClick={onClose}></div>
      <div className="fixed bottom-0 left-0 right-0 z-[2000] h-[72vh] rounded-t-3xl border-t-4 border-white/40 bg-white p-6 dark:border-zinc-700 dark:bg-zinc-900">
        <div className="mb-4 flex items-center justify-between">
          <h3 className="text-lg font-semibold text-zinc-900 dark:text-white">Comments: {activeChapter}</h3>
          <button className="text-xl text-zinc-400" onClick={onClose}>
            <i className="fa-solid fa-xmark"></i>
          </button>
        </div>

        <div className="mb-4 h-[45vh] overflow-y-auto space-y-3">
          {(comments || []).map((comment, idx) => {
            // Handle both old string format (fallback) and new object format
            const isObject = typeof comment === 'object' && comment !== null;
            const name = isObject ? comment.name : 'User';
            const text = isObject ? comment.text : comment;

            return (
              <div
                key={`${activeChapter}-${idx}`}
                className="rounded-xl bg-zinc-100 p-3 text-sm text-zinc-700 dark:bg-zinc-800 dark:text-zinc-200"
              >
                <b className="mb-0.5 block text-xs text-blue-600 dark:text-blue-400">{name}</b>
                <p>{text}</p>
              </div>
            );
          })}
          {(!comments || comments.length === 0) && (
            <p className="text-center text-zinc-500 py-10">No comments yet.</p>
          )}
        </div>

        <div className="border-t border-zinc-200 pt-4 dark:border-zinc-800">
          <div className="mb-3">
            <input
              value={nameValue}
              onChange={onNameChange}
              placeholder="Your Name (Optional)"
              className="w-full rounded-lg border border-zinc-200 bg-zinc-50 px-4 py-2 text-sm outline-none focus:border-blue-500 dark:border-zinc-700 dark:bg-zinc-800 dark:text-white"
            />
          </div>
          <div className="flex items-center gap-3">
            <input
              value={inputValue}
              onChange={onInputChange}
              placeholder="Add a comment..."
              className="flex-1 rounded-full border border-zinc-200 bg-zinc-100 px-5 py-3 text-sm text-zinc-800 outline-none focus:border-blue-500 dark:border-zinc-800 dark:bg-zinc-800 dark:text-zinc-200"
            />
            <button
              onClick={onSubmit}
              className="flex h-12 w-12 items-center justify-center rounded-full bg-blue-600 text-lg text-white shadow-md hover:bg-blue-700 transition"
            >
              <i className="fa-solid fa-paper-plane"></i>
            </button>
          </div>
        </div>
      </div>
    </>
  );
}

// --- src/components/modals/RatingModal.jsx ---
function RatingModal({ isOpen, currentRating, onSetRating, onSubmit }) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[3000] flex items-center justify-center bg-black/80">
      <div className="w-[320px] rounded-2xl border border-zinc-200 bg-white p-6 text-center dark:border-zinc-800 dark:bg-zinc-900">
        <h3 className="text-lg font-semibold text-zinc-900 dark:text-white">Rate Story</h3>
        <div className="my-6 text-3xl text-zinc-300">
          {[1, 2, 3, 4, 5].map((n) => (
            <i
              key={n}
              className={`fa-solid fa-star cursor-pointer transition ${currentRating >= n ? 'text-yellow-400' : 'text-zinc-300'}`}
              onClick={() => onSetRating(n)}
            ></i>
          ))}
        </div>
        <button onClick={onSubmit} className="w-full rounded-lg bg-white px-4 py-3 text-sm font-semibold text-black shadow-md">
          SUBMIT
        </button>
      </div>
    </div>
  );
}

// --- src/components/ui/FabPlay.jsx ---
function FabPlay({ onClick }) {
  return (
    <button
      onClick={onClick}
      className="fixed bottom-8 right-24 z-50 flex h-14 w-14 items-center justify-center rounded-full bg-white text-xl text-black shadow-lg transition hover:scale-105 dark:bg-white"
    >
      <i className="fa-solid fa-play"></i>
    </button>
  );
}

// --- src/components/ui/ThemeToggle.jsx ---
function ThemeToggle({ isDark, onToggle }) {
  return (
    <button
      onClick={onToggle}
      className="fixed bottom-7 right-7 z-[999] flex h-12 w-12 items-center justify-center rounded-full border border-zinc-200 bg-white text-lg text-zinc-500 transition hover:bg-zinc-200 hover:text-zinc-900 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-400 dark:hover:bg-zinc-800 dark:hover:text-white"
    >
      {isDark ? '☀️' : '🌙'}
    </button>
  );
}





















function App() {
  const [isNavOpen, setIsNavOpen] = useState(false);
  const [isDark, setIsDark] = useState(true);
  const [activePage, setActivePage] = useState('index');
  const [activeStoryId, setActiveStoryId] = useState(null);
  const [activeChapterId, setActiveChapterId] = useState(null);
  const [isReversed, setIsReversed] = useState(true);
  const [isSaved, setIsSaved] = useState(false);
  const [displayRating, setDisplayRating] = useState('4.9');
  const [currentRating, setCurrentRating] = useState(0);
  const [isRatingOpen, setIsRatingOpen] = useState(false);
  const [isComingSoonOpen, setIsComingSoonOpen] = useState(false);
  const [isCommentsOpen, setIsCommentsOpen] = useState(false);
  const [activeChapter, setActiveChapter] = useState('Ch. 1');
  const [commentInput, setCommentInput] = useState('');
  const [commentName, setCommentName] = useState('');
  const [commentsByChapter, setCommentsByChapter] = useState({});

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDark);
  }, [isDark]);

  useEffect(() => {
    const savedRating = localStorage.getItem('storyRating');
    if (savedRating) setDisplayRating(savedRating);
    setIsSaved(localStorage.getItem('isSaved') === 'true');
  }, []);

  useEffect(() => {
    localStorage.setItem('isSaved', isSaved ? 'true' : 'false');
  }, [isSaved]);

  const chapters = useMemo(() => (isReversed ? [...CHAPTERS].reverse() : [...CHAPTERS]), [isReversed]);

  useEffect(() => {
    const handleRoute = () => {
      const hash = window.location.hash.split('?')[0] || '#index';
      let pageId = hash.replace('#', '') || 'index';

      if (pageId.startsWith('reading/')) {
        setActiveStoryId(pageId.split('/')[1]);
        pageId = 'reading';
      } else if (pageId === 'reading') {
        setActiveStoryId(null);
      } else if (pageId.startsWith('read-chapter/')) {
        setActiveChapterId(pageId.split('/')[1]);
        pageId = 'chapter-reader';
      }

      setActivePage(pageId);
      window.scrollTo(0, 0);
    };

    handleRoute();
    window.addEventListener('hashchange', handleRoute);
    return () => window.removeEventListener('hashchange', handleRoute);
  }, []);

  useEffect(() => {
    if (activePage !== 'index') return;
    const ctx = gsap.context(() => {
      const heroTitle = gsap.utils.toArray('.hero-title');
      const heroSub = gsap.utils.toArray('.hero-sub');
      const heroCta = gsap.utils.toArray('.hero-cta');
      const cards = gsap.utils.toArray('.card-animate');
      if (heroTitle.length) gsap.from(heroTitle, { y: 18, opacity: 0, duration: 0.8, ease: 'power2.out' });
      if (heroSub.length) gsap.from(heroSub, { y: 14, opacity: 0, duration: 0.8, delay: 0.1, ease: 'power2.out' });
      if (heroCta.length) gsap.from(heroCta, { y: 12, opacity: 0, duration: 0.8, delay: 0.2, ease: 'power2.out', stagger: 0.1 });
      if (cards.length) gsap.from(cards, { y: 18, opacity: 0, duration: 0.7, delay: 0.25, ease: 'power2.out', stagger: 0.15 });
    });
    return () => ctx.revert();
  }, [activePage]);

  const openComments = (chapter) => {
    setActiveChapter(chapter);
    setIsCommentsOpen(true);
  };

  const closeComments = () => {
    setIsCommentsOpen(false);
    setCommentInput('');
    setCommentName('');
  };

  const postComment = () => {
    const text = commentInput.trim();
    const name = commentName.trim() || 'Anonymous';
    if (!text) return;
    setCommentsByChapter((prev) => ({
      ...prev,
      [activeChapter]: [...(prev[activeChapter] || []), { name, text, date: new Date().toISOString() }],
    }));
    setCommentInput('');
  };

  const submitRating = () => {
    if (currentRating === 0) {
      alert('Select stars first!');
      return;
    }
    const rating = `${currentRating}.0`;
    localStorage.setItem('storyRating', rating);
    setDisplayRating(rating);
    setIsRatingOpen(false);
  };

  return (
    <div className="min-h-screen bg-premium-cream text-premium-charcoal dark:bg-zinc-950 dark:text-zinc-100">
      <Sidebar isOpen={isNavOpen} onClose={() => setIsNavOpen((prev) => !prev)} />
      <SiteHeader onToggleNav={() => setIsNavOpen((prev) => !prev)} />

      {activePage === 'index' && (
        <main>
          <HeroSection isDark={isDark} />
          <RecentUpload />
          <ImageShowcase />
        </main>
      )}

      {activePage === 'reading' && (
        <ReadingPage
          storyId={activeStoryId}
          dummyChapters={chapters}
          displayRating={displayRating}
          isSaved={isSaved}
          onOpenRating={() => setIsRatingOpen(true)}
          onToggleSave={() => setIsSaved((prev) => !prev)}
          onSortToggle={() => setIsReversed((prev) => !prev)}
          onOpenComments={openComments}
          onBack={() => (window.location.hash = '#index')}
          isReversed={isReversed}
        />
      )}

      {activePage === 'chapter-reader' && (
        <ChapterReader chapterId={activeChapterId} onBack={() => window.history.back()} />
      )}

      {activePage === 'help' && <HelpCenter />}
      {activePage === 'about' && <About />}
      {activePage === 'contact' && <Contact />}
      {activePage === 'latest' && <LatestUpdates />}

      <Footer />
      <ThemeToggle isDark={isDark} onToggle={() => setIsDark((prev) => !prev)} />
      <FabPlay onClick={() => (window.location.hash = '#reading')} />

      <CommentsSheet
        isOpen={isCommentsOpen}
        activeChapter={activeChapter}
        comments={commentsByChapter[activeChapter]}
        inputValue={commentInput}
        onInputChange={(event) => setCommentInput(event.target.value)}
        nameValue={commentName}
        onNameChange={(event) => setCommentName(event.target.value)}
        onSubmit={postComment}
        onClose={closeComments}
      />
      <RatingModal
        isOpen={isRatingOpen}
        currentRating={currentRating}
        onSetRating={setCurrentRating}
        onSubmit={submitRating}
      />
      <ComingSoonModal isOpen={isComingSoonOpen} onClose={() => setIsComingSoonOpen(false)} />
    </div>
  );
}


export default App;
